#!/bin/sh
# generated by ctx v0.4.0 — regenerate with 'ctx harness init'
# ctx:checksum sha256:be19a79d422821c5444f4098c5b5c366b31cc058018a0b055ed958aa5e226c1e
# Stop hook: print a quality scorecard for the session's changes.
# Non-blocking by default: the scorecard goes to stdout, findings go to
# stderr, and the hook exits 0 (Claude Code does not show a Stop hook's
# stdout to the model). Set CTX_GATE_BLOCKING=1 to turn gate failures into a
# blocking stop (exit 2), with the scorecard and findings on stderr, which
# Claude Code feeds back to the model.
set -u

# Compat guard: if this binary is older than the templates that generated
# this script, warn (stderr) and fail open -- do nothing, exit 0.
ctx harness compat --require "0.4.0"
compat_status=$?
if [ "$compat_status" -eq 3 ]; then
    echo "ctx hooks: installed ctx is older than these hook templates (need 0.4.0); skipping stop action. Update ctx, then rerun 'ctx harness init'." >&2
    exit 0
elif [ "$compat_status" -ne 0 ]; then
    echo "ctx hooks: 'ctx harness compat' failed (status $compat_status); is ctx on PATH? Skipping stop action." >&2
    exit 0
fi

# Read the hook's JSON payload on stdin. `stop_hook_active` is true when
# Claude Code is already continuing because of a previous blocking Stop hook;
# blocking again then would loop for as long as the gate keeps failing.
payload=$(cat 2>/dev/null || true)
case "$payload" in
    *'"stop_hook_active":true'* | *'"stop_hook_active": true'*) stop_hook_active=1 ;;
    *) stop_hook_active=0 ;;
esac

# Quality scorecard vs the default branch, on stdout (on stderr when a gate
# fails in blocking mode). Exit 1 means a gate condition fired.
#
# Environment knobs:
#   CTX_GATE_BLOCKING=1 -- turn gate failures into exit 2, Claude Code's
#                          blocking-stop mechanism (the session keeps going
#                          until the findings are addressed).
#   CTX_GATE_LOG        -- consumed by `ctx score` itself (not this script):
#                          when set, each gate evaluation is appended to a
#                          local JSONL log (default .ctx/gate-log.jsonl).
#
# In blocking mode Claude Code shows the model only stderr (exit 2), never
# stdout, so the scorecard goes to stderr there; otherwise to stdout.
scorecard=$(ctx score --against main --fail-on "check_violations>0")
score_status=$?
if [ "$score_status" -eq 1 ] && [ "${CTX_GATE_BLOCKING:-0}" = "1" ] && [ "$stop_hook_active" = "0" ]; then
    printf '%s\n' "$scorecard" >&2
    echo "ctx hooks: quality gates failed (blocking mode); fix the failed conditions in the scorecard above before stopping." >&2
    exit 2
fi
[ -z "$scorecard" ] || printf '%s\n' "$scorecard"
if [ "$score_status" -eq 1 ]; then
    if [ "${CTX_GATE_BLOCKING:-0}" = "1" ]; then
        echo "ctx hooks: quality gates still fail after a blocked stop; not blocking again (stop_hook_active)." >&2
    else
        echo "ctx hooks: quality gates reported findings (non-blocking); see the scorecard above." >&2
    fi
fi
# Any other non-zero status is an operational error: fail open.
exit 0
